def test_knowledge_search_rejects_metadata_only_item():
    repo = copy_repo("knowledge-search-metadata-only-hard-cut")
    marker = "metadata-only-search-fixture-20260622"
    fixture_item = {
        "id": marker,
        "title": "Metadata only search fixture",
        "kind": "audit",
        "domain": "governance",
        "path": "artifacts/manifests/metadata-only-search-fixture-20260622.md",
        "scope": "team-general",
        "visibility": "team-internal",
        "status": "archived",
        "owner": "leiwenjun",
        "source": {"type": "generated", "source_id": "metadata-only-fixture-source", "from": "temporary regression fixture"},
        "tags": ["metadata-only-fixture", "knowledge-search", "governance"],
        "summary_zh": "只存在于 registry metadata 的搜索回归关键词，正文不包含该 marker。",
        "review_after": "2026-09-22",
        "review_status": "archive-only-regression-fixture",
        "validation_refs": ["tests:knowledge-search-metadata-only-hard-cut"],
        "promotion": "none",
        "searchable": True,
        "created_at": "2026-06-22",
        "updated_at": "2026-06-22",
    }
    with (repo / "registry" / "items.jsonl").open("a") as fh:
        fh.write(json.dumps(fixture_item, ensure_ascii=False, separators=(",", ":")) + "\n")
    result = run_cmd(
        repo,
        [
            "rtk",
            "bash",
            "tools/knowledge-search.sh",
            marker,
            "--source-id",
            "metadata-only-fixture-source",
            "--json",
            "--limit",
            "5",
        ],
    )
    expect(
        result["exit_code"] != 0
        and not result["stdout"].strip()
        and "registered search body is unavailable" in result["stderr"]
        and "artifacts/manifests/metadata-only-search-fixture-20260622.md"
        in result["stderr"],
        "knowledge-search-metadata-only-hard-cut",
        "knowledge search fails closed when searchable registry metadata has no canonical body",
        {
            "exit_code": result["exit_code"],
            "stdout_sample": result["stdout"][:1000],
            "stderr_sample": result["stderr"][:1000],
        },
        repo,
    )

def test_knowledge_search_invalid_filters():
    bad_status = run_cmd(root, ["rtk", "bash", "tools/knowledge-search.sh", "Knowledge Hub", "--status", "not-a-status"])
    bad_kind = run_cmd(root, ["rtk", "bash", "tools/knowledge-search.sh", "Knowledge Hub", "--kind", "not-a-kind"])
    bad_limit = run_cmd(root, ["rtk", "bash", "tools/knowledge-search.sh", "Knowledge Hub", "--limit", "0"])
    expect(
        bad_status["exit_code"] != 0
        and bad_kind["exit_code"] != 0
        and bad_limit["exit_code"] != 0
        and "invalid --status value" in bad_status["stderr"]
        and "invalid --kind value" in bad_kind["stderr"]
        and "--limit must be between 1 and 100" in bad_limit["stderr"],
        "knowledge-search-invalid-filters",
        "knowledge search rejects invalid enum filters and non-positive limits",
        {
            "bad_status_exit_code": bad_status["exit_code"],
            "bad_kind_exit_code": bad_kind["exit_code"],
            "bad_limit_exit_code": bad_limit["exit_code"],
            "bad_status_stderr": bad_status["stderr"][:500],
            "bad_kind_stderr": bad_kind["stderr"][:500],
            "bad_limit_stderr": bad_limit["stderr"][:500],
        },
    )

def _provider_context(query, *scopes, summary=False):
    command = ["rtk", "bash", "tools/knowledge-provider.sh", "context", "--cwd", str(root),
               "--query", query, "--context-budget", "small", "--limit", "3",
               "--summary-json" if summary else "--json", *scopes]
    result = run_cmd(root, command)
    try:
        payload = json.loads(result["stdout"])
    except (ValueError, TypeError):
        payload = {}
    return result, payload


def test_knowledge_context_budget_explainability():
    result, payload = _provider_context("PCR02 OTA 归档路径", "--retrieval-project", "pcr02-ssc305", summary=True)
    items = [item for group in payload.get("context", []) for item in group["items"]]
    expect(result["exit_code"] == 0 and payload.get("schema_version") == "knowledge-provider.context/v4"
           and payload.get("read_only") is True and 0 < len(items) <= 3
           and len({item["id"] for item in items}) == len(items)
           and len(result["stdout"].strip().encode("utf-8")) <= 4096
           and all(item.get("path") and item.get("why_selected") for item in items),
           "knowledge-context-budget-explainability", "Provider v4 returns bounded, deduplicated, traceable retrieval",
           {"exit_code": result["exit_code"], "context": payload.get("context"), "stderr": result["stderr"][:500]})


def test_knowledge_context_self_route():
    result, payload = _provider_context("增强 Knowledge Hub 自举体验", "--execution-project", "knowledge-hub")
    expect(result["exit_code"] == 0 and payload.get("execution_subject") == {"type": "project", "id": "knowledge-hub"}
           and payload.get("retrieval_scope") == [{"type": "project", "id": "knowledge-hub"}],
           "knowledge-context-self-route", "Explicit Hub execution subject resolves independently of ranking",
           {"exit_code": result["exit_code"], "execution_subject": payload.get("execution_subject")})


def test_knowledge_context_control_plane_query_override():
    result, payload = _provider_context("PCR02 OTA 归档路径", "--execution-project", "knowledge-hub",
                                        "--retrieval-project", "pcr02-ssc305")
    expect(result["exit_code"] == 0 and payload.get("execution_subject") == {"type": "project", "id": "knowledge-hub"}
           and payload.get("retrieval_scope") == [{"type": "project", "id": "pcr02-ssc305"}],
           "knowledge-context-control-plane-query-override",
           "Cross-project retrieval keeps explicit execution and archival identity unchanged",
           {"exit_code": result["exit_code"], "execution_subject": payload.get("execution_subject"),
            "retrieval_scope": payload.get("retrieval_scope")})


